import{_ as t,o,c as i,a2 as a}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Conservazione dei dati e cancellazione GDPR","description":"","frontmatter":{},"headers":[],"relativePath":"security/data-retention.md","filePath":"security/data-retention.md"}'),d={name:"security/data-retention.md"};function n(l,e,c,r,s,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="conservazione-dei-dati-e-cancellazione-gdpr" tabindex="-1">Conservazione dei dati e cancellazione GDPR <a class="header-anchor" href="#conservazione-dei-dati-e-cancellazione-gdpr" aria-label="Permalink to &quot;Conservazione dei dati e cancellazione GDPR&quot;">​</a></h1><p>Stato: M7-WP2. Descrive, per ogni classe di dato, <strong>quanto a lungo viene conservata</strong>, <strong>quale impostazione la governa</strong> e <strong>che cosa le fa la cancellazione dell&#39;account</strong> (<code>DELETE /me</code>, ADR-0021). I valori predefiniti sono quelli del codice alla data di redazione; le impostazioni di sistema si modificano dalla console admin (o direttamente nella tabella <code>settings</code>) senza riavvio.</p><h2 id="_1-classi-di-dato" tabindex="-1">1. Classi di dato <a class="header-anchor" href="#_1-classi-di-dato" aria-label="Permalink to &quot;1. Classi di dato&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classe</th><th>Dove</th><th>Periodo predefinito</th><th>Controllo</th><th>Effetto della cancellazione dell&#39;account</th></tr></thead><tbody><tr><td>Profilo utente (<code>users</code>: username, email, nome, ruolo, quota)</td><td>PostgreSQL</td><td>Finché l&#39;account esiste</td><td>—</td><td><strong>Anonimizzato subito</strong>: username <code>deleted-&lt;8 car. dell&#39;id&gt;</code>, email <code>deleted-&lt;id&gt;@deleted.invalid</code>, nome <code>NULL</code>. La riga (id, ruolo, date, <code>keycloak_sub</code>) resta come <em>tombstone</em> per l&#39;integrità di audit e revisioni. Al purge anche <code>keycloak_sub</code> diventa <code>purged:&lt;id&gt;</code></td></tr><tr><td>Dispositivi (<code>devices</code>)</td><td>PostgreSQL</td><td>Finché l&#39;account esiste; i revocati restano elencati</td><td>—</td><td>Cancellati; quelli ancora referenziati da revisioni sono revocati e resi anonimi (<code>deleted device</code>)</td></tr><tr><td>Appartenenze a gruppi (<code>group_members</code>)</td><td>PostgreSQL</td><td>Finché l&#39;account esiste</td><td>—</td><td>Cancellate subito</td></tr><tr><td>Share e grant</td><td>PostgreSQL</td><td>Finché non revocati/scaduti</td><td><code>expires_at</code> della share</td><td>Grant <strong>verso</strong> l&#39;utente e grant <strong>concessi da</strong> lui cancellati subito; le share su vault di terzi restano</td></tr><tr><td>Blob dei vault (contenuto corrente)</td><td>S3 + <code>blobs</code></td><td>Finché referenziati</td><td>Quota utente (D-03: conta solo i file correnti)</td><td>Rilasciati con il purge del vault; poi GC</td></tr><tr><td>Revisioni (<code>file_revisions</code>)</td><td>PostgreSQL</td><td>Tutte per <code>history.retention_days</code> (30), poi l&#39;ultima di ogni giorno UTC fino a <code>history.daily_retention_days</code> (90), poi nulla; la revisione corrente non è mai potata</td><td><code>history.retention_days</code>, <code>history.daily_retention_days</code></td><td>Rimosse con il vault dell&#39;utente; le revisioni che l&#39;utente ha scritto in <strong>vault di altri</strong> restano, con <code>author_id</code> che punta al tombstone anonimo</td></tr><tr><td>Blob non referenziati</td><td>S3 + <code>blobs</code></td><td>24 h di grazia, poi cancellati</td><td><code>blobs.gc_grace_hours</code></td><td>Nessun effetto diretto: il GC raccoglie i blob liberati dal purge</td></tr><tr><td>Upload tus incompleti (<code>uploads</code>)</td><td>PostgreSQL + S3</td><td>24 h</td><td><code>uploads.expiry_hours</code></td><td>Cancellati al ciclo successivo del job <code>uploads</code> (ogni 15 min per default), righe e chunk insieme; uno sweep rimuove anche i chunk rimasti senza riga</td></tr><tr><td>Changelog dei vault (finestra di sync)</td><td>PostgreSQL</td><td>90 giorni serviti ai client; oltre, bootstrap dal manifest</td><td><code>sync.changelog_window_days</code></td><td>Segue il vault</td></tr><tr><td>Vault eliminati (soft delete)</td><td>PostgreSQL + S3</td><td>30 giorni, poi purge fisico</td><td><code>vaults.deleted_retention_days</code></td><td>I vault dell&#39;utente sono eliminati (soft) all&#39;istante e <strong>purgati dopo <code>privacy.account_purge_days</code></strong> (30), anche se <code>vaults.deleted_retention_days</code> è più lungo</td></tr><tr><td>Envelope di chiavi dei vault privati</td><td>PostgreSQL</td><td>Con il vault</td><td>—</td><td>Cancellati con il purge del vault. <strong>I dati dei vault privati non sono recuperabili da nessuno</strong> (D-02)</td></tr><tr><td>Archivi di export ZIP (<code>export_jobs</code>, bucket export)</td><td>S3</td><td>24 h dal completamento</td><td><code>export.LinkTTL</code> (costante)</td><td>Le righe <code>ready</code> dell&#39;utente scadono subito e il job <code>exports</code> cancella gli oggetti (ciclo da 15 s)</td></tr><tr><td>Registro di audit (<code>audit_log</code>)</td><td>PostgreSQL</td><td><strong>Nessuna scadenza automatica</strong> (vedi §3)</td><td>—</td><td>Righe conservate (traccia), ma <code>ip</code> azzerato e <code>details.username</code> rimosso per le righe dove l&#39;utente è attore o bersaglio. Gli id restano</td></tr><tr><td>Indice di storage giornaliero (<code>storage_snapshots</code>)</td><td>PostgreSQL</td><td>Illimitata (un valore al giorno, aggregato, nessun dato personale)</td><td>—</td><td>Nessuno</td></tr><tr><td>Account Keycloak (credenziali, email, sessioni)</td><td>Keycloak</td><td>Gestito da Keycloak</td><td>Configurazione del realm</td><td><strong>Disabilitato</strong> e sessioni terminate (<code>keycloak.Admin.SetEnabled(false)</code>); <strong>non cancellato</strong> da Clarae notanda (§4)</td></tr><tr><td>Snapshot locali del desktop (<code>.clarae/snapshots</code>)</td><td>Disco del dispositivo</td><td>7 giorni, max 5 MB/file e 500 MB totali</td><td>Impostazioni &quot;Ripristino file&quot; (<code>retentionDays</code>, <code>maxFileMB</code>, <code>maxTotalMB</code>)</td><td>Nessun effetto: dati solo locali, sotto controllo dell&#39;utente</td></tr><tr><td>Log applicativi</td><td>stdout del cloud</td><td>Secondo l&#39;infrastruttura (fuori dal codice)</td><td>Configurazione del cluster</td><td>Contengono id utente e IP della richiesta (<code>RequestLogger</code>): applicare la retention dell&#39;aggregatore di log (consigliato ≤ 30 giorni)</td></tr><tr><td>Presenza in tempo reale (stanze, nome visualizzato e posizione del puntatore)</td><td>Solo memoria del processo del cloud</td><td>Finché il file è aperto e la connessione viva; un membro annunciato da un&#39;altra replica scade dopo 70 s senza rinnovo; <strong>nessuna persistenza</strong></td><td><code>features.presence</code> del Config Profile (l&#39;amministratore può spegnerla)</td><td>Nessun dato da cancellare: nessuna tabella, nessun audit, nessun log per frame né per posizione. Le connessioni dell&#39;utente sospeso o cancellato si chiudono. Apertura e chiusura di una connessione sono log di livello <code>debug</code> con <code>user_id</code> e <code>sid</code></td></tr></tbody></table><h2 id="_2-cosa-succede-alla-cancellazione-delete-me" tabindex="-1">2. Cosa succede alla cancellazione (<code>DELETE /me</code>) <a class="header-anchor" href="#_2-cosa-succede-alla-cancellazione-delete-me" aria-label="Permalink to &quot;2. Cosa succede alla cancellazione (`DELETE /me`)&quot;">​</a></h2><p>Richiede <code>confirm</code> uguale allo username e, se l&#39;utente possiede vault privati, <code>acknowledge_data_loss: true</code>. In un&#39;unica transazione:</p><ol><li>verifica dell&#39;ultimo amministratore attivo (rifiuto <code>INVALID_STATE</code>; blocco delle righe admin contro cancellazioni concorrenti);</li><li>vault dell&#39;utente eliminati (soft);</li><li>anonimizzazione del profilo, dei dispositivi e dell&#39;audit (IP e username);</li><li>rimozione di appartenenze, grant ricevuti e concessi, upload in corso; scadenza degli export pronti;</li><li>voce di audit <code>account.delete</code> (solo id e conteggi) e notifica di sospensione ai client connessi.</li></ol><p>Poi, fuori transazione: invalidazione della cache di autenticazione e disabilitazione dell&#39;account Keycloak (se non è configurato o l&#39;utente non esiste, l&#39;operazione prosegue).</p><p>Dopo <code>privacy.account_purge_days</code> il job di manutenzione (<code>PurgeDeletedAccounts</code>, giornaliero) elimina fisicamente ogni vault dell&#39;utente (righe, file, revisioni, envelope; riferimenti ai blob rilasciati e quota), ripete l&#39;anonimizzazione (copre anche gli account cancellati da un amministratore con <code>DELETE /admin/users/{id}</code>, che prima resta una cancellazione logica) e marca la riga come <code>purged</code>. I blob rimasti senza riferimenti sono rimossi dal GC dopo <code>blobs.gc_grace_hours</code>.</p><p>Un account cancellato non può essere riattivato né riprovisionato dallo stesso soggetto Keycloak: il login risponde <code>USER_SUSPENDED</code> e la riga non viene mai riscritta con dati personali (<code>UpsertUserFromToken</code>).</p><h2 id="_3-lacune-dichiarate" tabindex="-1">3. Lacune dichiarate <a class="header-anchor" href="#_3-lacune-dichiarate" aria-label="Permalink to &quot;3. Lacune dichiarate&quot;">​</a></h2><ul><li><strong>Audit log senza retention</strong>: oggi cresce senza limite. Proposta (da decidere): impostazione <code>audit.retention_days</code> e job di potatura. Va bilanciata con l&#39;obbligo di tracciare le azioni amministrative; la riga anonimizzata non contiene dati personali diretti.</li><li><strong>Keycloak</strong>: Clarae notanda disabilita, non elimina, l&#39;account. L&#39;eliminazione definitiva (e di email, credenziali, cronologia eventi) è un&#39;operazione del gestore del realm; <code>keycloak.Admin</code> non espone <code>DeleteUser</code>. Fino ad allora il gestore deve cancellare gli account disabilitati secondo la propria policy.</li><li><strong>Export ZIP di vault eliminati</strong>: le righe <code>export_jobs</code> seguono il vault (cascade) ma l&#39;oggetto S3 viene rimosso dal job <code>exports</code> solo alla scadenza; la scadenza forzata alla cancellazione dell&#39;account copre il caso dell&#39;utente, non quello di un vault purgato per altra via.</li><li><strong>Backup</strong>: i backup del database e del bucket (M7-WP2b) contengono i dati fino alla scadenza del backup; la cancellazione non li riscrive. Documentare nella policy di backup la durata massima (consigliato ≤ 35 giorni).</li><li><strong>Dati sui dispositivi dell&#39;utente</strong>: la cancellazione non tocca i vault locali dei client desktop.</li></ul><h2 id="_4-verifica" tabindex="-1">4. Verifica <a class="header-anchor" href="#_4-verifica" aria-label="Permalink to &quot;4. Verifica&quot;">​</a></h2><p>Ogni riga sopra, tranne i log e Keycloak, è coperta da <code>services/cloud/test/integration/privacy_test.go</code> (export completo, anonimizzazione, audit senza IP, grant rimossi, vault e blob purgati, nessuna risurrezione al login, ultimo admin, account cancellati da un amministratore) e dai test esistenti di <code>jobs_test.go</code> (GC, retention revisioni, purge vault).</p>',14)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
